// ULID simplificado — só precisa ser único e ordenável por tempo para
// reconstruir a execução nos logs; não precisa da implementação completa
// de supabase/functions/_shared/correlation.ts, que já cobre o caso mais
// rigoroso (monotonicidade dentro do mesmo milissegundo) do lado da Edge
// Function.
const ALPHABET = '0123456789ABCDEFGHJKMNPQRSTVWXYZ';
function encodeTime(ms) {
  let out = '';
  let t = ms;
  for (let i = 0; i < 10; i++) {
    out = ALPHABET[t % 32] + out;
    t = Math.floor(t / 32);
  }
  return out;
}
function randomPart() {
  let out = '';
  for (let i = 0; i < 16; i++) {
    out += ALPHABET[Math.floor(Math.random() * 32)];
  }
  return out;
}
return [{ json: { correlationId: encodeTime(Date.now()) + randomPart() } }];
